// Writes the RecordRegistry ABI from Foundry's output into packages/chain/src/abi.ts.
// Run through `pnpm contracts:build`; the generated file must not be edited by hand.
import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const root = join(import.meta.dirname, "..");
const artifact = JSON.parse(readFileSync(join(root, "contracts/out/RecordRegistry.sol/RecordRegistry.json"), "utf8"));
const source = `// Generated by scripts/export-abi.mjs from contracts/src/RecordRegistry.sol. Do not edit.
export const recordRegistryAbi = ${JSON.stringify(artifact.abi, null, 2)} as const;

export const recordRegistryBytecode = ${JSON.stringify(artifact.bytecode.object)} as const;
`;
writeFileSync(join(root, "packages/chain/src/abi.ts"), source);
console.log(`RecordRegistry: ${(artifact.deployedBytecode.object.length - 2) / 2} bytes runtime`);
